import React, { useEffect } from 'react';
import '../types';

const ChatWidget: React.FC = () => {
  useEffect(() => {
    // Check if script is already present to avoid duplicates
    if (document.querySelector('script[src="https://adventureland-ai.com/widget.v1.js"]')) {
      return;
    }

    const script = document.createElement('script');
    script.src = "https://adventureland-ai.com/widget.v1.js";
    script.async = true;
    script.onload = () => {
      if (window.WonderWidget) {
        window.WonderWidget.init({
          "theme": {
            "primaryColor": "#ef4444",
            "secondaryColor": "#ffffff",
            "fontColor": "#1f2937",
            "botName": "AdventureBot",
            "botAvatar": "data:image/png;base64,",
            "welcomeMessage": "Hi there! I'm Alfie, and I'm here to help plan your Adventureland visit. What can I do for you today?",
            "headerTitle": "Ask Alfie",
            "position": "bottom-right"
          }
        });
      }
    };
    document.body.appendChild(script);

    return () => {
      // Cleanup is tricky with external scripts appending global objects, 
      // but we can try to remove the script tag.
      if (document.body.contains(script)) {
        document.body.removeChild(script);
      }
    };
  }, []);

  return null;
};

export default ChatWidget;